/**
 * @summary Get trending products by category
 */
export const getGetTrendingProductsUrl = (
  params?: GetTrendingProductsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/shopping/trending?${stringifiedParams}`
    : `/api/shopping/trending`;
};

export const getTrendingProducts = async (
  params?: GetTrendingProductsParams,
  options?: RequestInit,
): Promise<Product[]> => {
  return customFetch<Product[]>(getGetTrendingProductsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetTrendingProductsQueryKey = (
  params?: GetTrendingProductsParams,
) => {
  return [`/api/shopping/trending`, ...(params ? [params] : [])] as const;
};

export const getGetTrendingProductsQueryOptions = <
  TData = Awaited<ReturnType<typeof getTrendingProducts>>,
  TError = ErrorType<unknown>,
>(
  params?: GetTrendingProductsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTrendingProducts>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetTrendingProductsQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getTrendingProducts>>
  > = ({ signal }) =>
    getTrendingProducts(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getTrendingProducts>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

